// MAIRFM Car Mode — music-first navigation + Journey context
(()=>{
'use strict';
if(window.MAIRCarModePrototype?.version?.includes?.('journey-nav'))return;
const $=id=>document.getElementById(id),CFG='/api/config';
let overlay=null,open=false,wake=null,wakeRetry=null,searchTimer=null,searchAbort=null,routeAbort=null,refreshTimer=null,token='',recents=[];
const s={screen:'home',routeActive:false,origin:null,destination:null,route:null,steps:[],step:0,pos:null,watch:null,near:false,error:'',loading:false,lastRoute:0,off:0,searchQuery:'',searchResults:[]};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dist=m=>!Number.isFinite(m)?'—':m<1000?`${Math.max(10,Math.round(m/10)*10)} M`:`${m/1000<10?(m/1000).toFixed(1):Math.round(m/1000)} KM`;
const dur=x=>{if(!Number.isFinite(x))return'—';const m=Math.max(0,Math.round(x/60));return m<60?`${m} MIN`:`${Math.floor(m/60)}U ${String(m%60).padStart(2,'0')}M`};
const eta=x=>Number.isFinite(x)?new Intl.DateTimeFormat('nl-NL',{hour:'2-digit',minute:'2-digit'}).format(new Date(Date.now()+x*1000)):'--:--';
function play(){try{const p=window.JFMPlaybackState?.get?.()||{},img=$('artImg');return{title:String($('title')?.textContent||p.title||p.name||'MAIRFM').trim(),artist:String($('artist')?.textContent||p.artist||'').trim(),image:String(img?.currentSrc||img?.src||'mair-icon-512.png'),isPlaying:typeof p.isPlaying==='boolean'?p.isPlaying:!!p.expectedLive,progress:Number(p.progressMs||p.progress_ms||0),duration:Number(p.durationMs||p.duration_ms||0)}}catch{return{title:'MAIRFM',artist:'',image:'mair-icon-512.png',isPlaying:false,progress:0,duration:0}}}
function next(){try{return(window.jfmUpcoming?.()||[])[0]||null}catch{return null}}
async function config(){try{const r=await fetch(CFG,{cache:'no-store'});if(r.ok)token=String((await r.json()).mapboxPublicToken||'').trim()}catch{}return token}
const hav=(a,b)=>{if(!a||!b)return Infinity;const R=6371000,r=x=>x*Math.PI/180,d1=r(b.latitude-a.latitude),d2=r(b.longitude-a.longitude),q=Math.sin(d1/2)**2+Math.cos(r(a.latitude))*Math.cos(r(b.latitude))*Math.sin(d2/2)**2;return 2*R*Math.asin(Math.sqrt(q))};
const geo=opts=>new Promise((ok,no)=>navigator.geolocation?.getCurrentPosition(ok,no,opts||{enableHighAccuracy:true,timeout:10000,maximumAge:10000})||no(Error('Locatie niet beschikbaar.')));
async function search(q){q=String(q||'').trim();if(q.length<2)return[];if(!token)throw Error('Mapbox-token ontbreekt.');searchAbort?.abort();searchAbort=new AbortController();const prox=s.pos?`&proximity=${s.pos.longitude},${s.pos.latitude}`:'';const r=await fetch(`https://api.mapbox.com/search/geocode/v6/forward?q=${encodeURIComponent(q)}&country=nl&language=nl&limit=6${prox}&access_token=${encodeURIComponent(token)}`,{signal:searchAbort.signal});if(!r.ok)throw Error(`Adres zoeken mislukt (${r.status}).`);const d=await r.json();return(d.features||[]).map(f=>{const c=f.geometry?.coordinates||[],p=f.properties||{};return{name:p.name||p.full_address||f.place_name||q,address:p.full_address||p.place_formatted||f.place_name||'',longitude:Number(c[0]),latitude:Number(c[1])}}).filter(x=>Number.isFinite(x.longitude)&&Number.isFinite(x.latitude))}
async function route(force=false){if(!s.origin||!s.destination)throw Error('Kies eerst een bestemming.');if(!token)throw Error('Mapbox-token ontbreekt.');if(!force&&Date.now()-s.lastRoute<15000&&s.route)return s.route;routeAbort?.abort();routeAbort=new AbortController();s.loading=true;render();const pts=[s.origin,s.destination].map(p=>`${p.longitude},${p.latitude}`).join(';'),qs=new URLSearchParams({access_token:token,alternatives:'false',steps:'true',banner_instructions:'true',geometries:'geojson',overview:'full',language:'nl',voice_units:'metric',roundabout_exits:'true'});try{const r=await fetch(`https://api.mapbox.com/directions/v5/mapbox/driving-traffic/${pts}?${qs}`,{signal:routeAbort.signal});if(!r.ok)throw Error(`Route berekenen mislukt (${r.status}).`);const d=await r.json(),rt=d.routes?.[0];if(!rt)throw Error('Geen autoroute gevonden.');s.route=rt;s.steps=(rt.legs||[]).flatMap(l=>l.steps||[]);s.step=Math.min(s.step,Math.max(0,s.steps.length-1));s.lastRoute=Date.now();s.loading=false;publish();render();return rt}catch(e){s.loading=false;if(e?.name==='AbortError')return null;s.error=e?.message||'Route kon niet worden berekend.';render();throw e}}
const mpoint=st=>Array.isArray(st?.maneuver?.location)?{longitude:Number(st.maneuver.location[0]),latitude:Number(st.maneuver.location[1])}:null;
const currentStep=()=>s.steps[Math.min(s.step,Math.max(0,s.steps.length-1))]||null,nextStep=()=>s.steps[Math.min(s.step+1,Math.max(0,s.steps.length-1))]||currentStep();
function metrics(){if(!s.route)return{distance:null,duration:null};let distance=0,duration=0;for(let i=s.step;i<s.steps.length;i++){distance+=Number(s.steps[i]?.distance||0);duration+=Number(s.steps[i]?.duration||0)}return{distance:distance||Number(s.route.distance||0),duration:duration||Number(s.route.duration||0)}}
function progress(){const total=Number(s.route?.distance||0),rem=metrics().distance;return total&&Number.isFinite(rem)?Math.max(0,Math.min(1,1-rem/total)):0}
function nearDistance(){const p=mpoint(nextStep());return s.pos&&p?hav(s.pos,p):Number(nextStep()?.distance||Infinity)}
function updateNav(){if(!s.pos||!s.steps.length)return;const ni=Math.min(s.step+1,s.steps.length-1),np=mpoint(s.steps[ni]);if(np&&hav(s.pos,np)<45)s.step=ni;const d=nearDistance(),v=Math.max(0,Number(s.pos.speed||0));s.near=Number.isFinite(d)&&d<=(v>22?900:v>12?650:450);const candidates=s.steps.slice(s.step,s.step+4).map(mpoint).filter(Boolean).map(p=>hav(s.pos,p));const nearest=Math.min(...candidates,Infinity);s.off=nearest>350?s.off+1:0;if(s.off>=3&&Date.now()-s.lastRoute>30000){s.off=0;s.origin={name:'Huidige locatie',latitude:s.pos.latitude,longitude:s.pos.longitude};route(true).catch(()=>{})}publish();render()}
function watch(){unwatch();if(!navigator.geolocation)return;s.watch=navigator.geolocation.watchPosition(p=>{s.pos={latitude:p.coords.latitude,longitude:p.coords.longitude,speed:Number(p.coords.speed||0),accuracy:p.coords.accuracy};updateNav()},()=>{s.error='Live locatie tijdelijk niet beschikbaar.';render()},{enableHighAccuracy:true,maximumAge:3000,timeout:15000})}
function unwatch(){if(s.watch!=null&&navigator.geolocation)navigator.geolocation.clearWatch(s.watch);s.watch=null}
function startRefresh(){stopRefresh();if(!s.routeActive)return;refreshTimer=setInterval(()=>{if(!open||!s.routeActive||document.visibilityState!=='visible'||!s.pos)return;s.origin={name:'Huidige locatie',latitude:s.pos.latitude,longitude:s.pos.longitude};route(true).catch(()=>{})},120000)}
function stopRefresh(){if(refreshTimer){clearInterval(refreshTimer);refreshTimer=null}}
function publish(){const m=metrics(),detail={active:!!s.routeActive,destination:s.destination?.name||'',remainingTravelTime:m.duration,arrivalTime:Number.isFinite(m.duration)?Date.now()+m.duration*1000:null,remainingDistance:m.distance,routeProgress:progress(),stopsRemaining:0,nextManeuver:nextStep()?.maneuver?.instruction||''};window.MAIRJourneyContext=detail;try{window.dispatchEvent(new CustomEvent('mair:journey-context',{detail}))}catch{}}
function transport(a){const id=a==='play'?'play':a==='prev'?'prev':a==='next'?'next':'',el=id?$(id):null;if(el){el.click();setTimeout(render,100);return}if(a==='play')window.JFMPlayback?.playPause?.()}
function like(){$('loveTrack')?.click()}
function icon(st){const m=st?.maneuver?.modifier||'',t=st?.maneuver?.type||'';if(t==='roundabout'||t==='rotary')return'↻';if(m.includes('left'))return'↰';if(m.includes('right'))return'↱';if(m==='uturn')return'↶';return'↑'}
const instr=st=>String(st?.maneuver?.instruction||st?.name||'Route volgen').trim();
function startMarkup(){const rs=recents.slice(0,5).map((r,i)=>`<button data-recent="${i}"><b>${esc(r.name)}</b><small>${esc(r.address||'')}</small></button>`).join('');return`<section class="car-start"><div class="car-brand"><span>MAIRFM</span><strong>CAR MODE</strong></div><div class="car-start-main"><p>MUZIEK EERST. ROUTE WANNEER JE HEM NODIG HEBT.</p><button class="car-choice primary" data-act="search"><b>⌖ KIES BESTEMMING</b><span>Route, ETA en afslaginfo</span></button><button class="car-choice" data-act="music"><b>▶ START ZONDER ROUTE</b><span>Volledig muziekgericht</span></button></div><div class="car-recents"><span>RECENT</span>${rs||'<small>Nog geen bestemmingen in deze sessie</small>'}</div></section>`}
function searchMarkup(){const rs=s.searchResults.map((x,i)=>`<button data-result-index="${i}"><b>${esc(x.name)}</b><small>${esc(x.address)}</small></button>`).join('');return`<section class="car-search"><header><button class="car-back" data-act="home">‹</button><div><small>CAR MODE</small><strong>Waar wil je heen?</strong></div></header><label class="car-searchbox"><span>⌕</span><input id="carSearchInput" autocomplete="off" placeholder="Adres of plaats" value="${esc(s.searchQuery)}"></label>${s.error?`<div class="car-search-error">${esc(s.error)}</div>`:''}<div id="carSearchStatus" class="car-search-status"></div><div id="carSearchResults" class="car-search-results">${rs}</div><button class="car-text-action" data-act="music">Verder zonder route</button></section>`}
function previewMarkup(){const m=metrics();return`<section class="car-preview"><header><button class="car-back" data-act="search">‹</button><div><small>ROUTE</small><strong>${esc(s.destination?.name||'Bestemming')}</strong></div></header><div class="car-preview-card"><div><small>VAN</small><b>Huidige locatie</b></div><div><small>NAAR</small><b>${esc(s.destination?.name||'')}</b></div><div><small>AANKOMST</small><b>${eta(m.duration)}</b></div></div><div class="car-preview-metrics"><div><small>TIJD</small><b>${dur(m.duration)}</b></div><div><small>AFSTAND</small><b>${dist(m.distance)}</b></div><div><small>VERKEER</small><b>LIVE</b></div></div><button class="car-route-start" data-act="start">ROUTE STARTEN</button></section>`}
function navMarkup(){const st=nextStep(),m=metrics(),d=nearDistance();return`<aside class="car-nav-card"><div class="car-nav-top"><span>VOLGENDE</span><span>${eta(m.duration)}</span></div><div class="car-nav-maneuver"><div class="car-nav-arrow">${icon(st)}</div><div><b>${dist(d)}</b><strong>${esc(instr(st))}</strong></div></div><div class="car-nav-bottom"><span>${dur(m.duration)}</span><span>${dist(m.distance)}</span></div><div class="car-route-progress"><i style="width:${Math.round(progress()*100)}%"></i></div></aside>`}
function player(withNav){const p=play(),n=next(),pct=p.duration>0?Math.max(0,Math.min(100,p.progress/p.duration*100)):0,nm=n?.name||n?.title||'Wordt bepaald',na=Array.isArray(n?.artists)?n.artists.join(', '):n?.artist||'';return`<section class="car-drive ${withNav?'':'music-only'}"><header class="car-drive-head"><strong>MAIRFM <span>${withNav?'· JOURNEY':'· MUSIC'}</span></strong><button class="car-more" data-act="menu">•••</button></header><div class="car-drive-grid"><div class="car-music"><img class="car-artwork" src="${esc(p.image||'mair-icon-512.png')}" alt=""><div class="car-track-copy"><small>NU SPEELT</small><h1>${esc(p.title)}</h1><p>${esc(p.artist)}</p><div class="car-track-progress"><i style="width:${pct}%"></i></div><div class="car-controls"><button data-like>♡</button><button data-tr="prev">‹</button><button class="car-play" data-tr="play">${p.isPlaying?'Ⅱ':'▶'}</button><button data-tr="next">›</button></div></div><div class="car-next"><small>VOLGENDE</small><b>${esc(nm)}</b><span>${esc(na)}</span></div></div>${withNav?navMarkup():''}</div>${s.error?`<div class="car-toast">${esc(s.error)} <button data-act="dismiss">×</button></div>`:''}</section>`}
function focusMarkup(){const p=play(),st=nextStep(),m=metrics();return`<section class="car-turn-focus"><header><div><small>${esc(p.title)}</small><span>${esc(p.artist)}</span></div><button class="car-more" data-act="menu">•••</button></header><div class="car-turn-hero"><div class="car-turn-arrow">${icon(st)}</div><div><b>${dist(nearDistance())}</b><h1>${esc(instr(st))}</h1><span>${eta(m.duration)} · ${dur(m.duration)}</span></div></div><div class="car-turn-controls"><button data-tr="play">${p.isPlaying?'Ⅱ':'▶'}</button><button data-tr="next">›</button></div></section>`}
function menu(){return`<div class="car-menu-backdrop"><section class="car-menu">${s.routeActive?'<button data-act="search">Bestemming wijzigen</button><button data-act="waze">Open in Waze</button><button data-act="music">Verder zonder route</button>':'<button data-act="search">Bestemming toevoegen</button>'}<button data-act="time">Time Machine</button><button class="danger" data-act="close">Car Mode sluiten</button><button class="muted" data-act="menuclose">Annuleren</button></section></div>`}
function ensure(){if(overlay)return overlay;overlay=document.createElement('div');overlay.id='mairCarWaveOverlay';overlay.className='mair-car-wave-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');document.body.appendChild(overlay);overlay.addEventListener('click',async e=>{const tr=e.target.closest('[data-tr]');if(tr){transport(tr.dataset.tr);return}if(e.target.closest('[data-like]')){like();return}const rr=e.target.closest('[data-recent]');if(rr){const d=recents[Number(rr.dataset.recent)];if(d){s.destination=d;s.error='';await prepare()}return}const res=e.target.closest('[data-result-index]');if(res){const d=s.searchResults[Number(res.dataset.resultIndex)];if(d){s.destination={...d};s.error='';await prepare()}return}const a=e.target.closest('[data-act]')?.dataset.act;if(!a)return;if(a==='home'){s.routeActive=false;s.screen='home';unwatch();stopRefresh();publish();render()}else if(a==='search'){closeMenu();s.screen='search';render();queueMicrotask(bindSearch)}else if(a==='music'){s.routeActive=false;s.screen='music';unwatch();stopRefresh();publish();render()}else if(a==='start'){s.routeActive=true;s.screen='drive';if(s.destination)recents=[s.destination,...recents.filter(x=>x.longitude!==s.destination.longitude||x.latitude!==s.destination.latitude)].slice(0,5);watch();startRefresh();publish();render()}else if(a==='menu'){if(!overlay.querySelector('.car-menu-backdrop'))overlay.insertAdjacentHTML('beforeend',menu())}else if(a==='menuclose')closeMenu();else if(a==='dismiss'){s.error='';render()}else if(a==='waze'){if(s.destination)location.href=`https://waze.com/ul?ll=${encodeURIComponent(`${s.destination.latitude},${s.destination.longitude}`)}&navigate=yes`}else if(a==='time'){closeMenu();setOpen(false);document.querySelector('[data-mode="throwback"]')?.click()}else if(a==='close'){closeMenu();setOpen(false)}});return overlay}
function closeMenu(){overlay?.querySelector('.car-menu-backdrop')?.remove()}
function bindSearch(){const input=$('carSearchInput'),out=$('carSearchResults'),status=$('carSearchStatus');if(!input||input.dataset.bound)return;input.dataset.bound='1';input.focus();input.addEventListener('input',()=>{clearTimeout(searchTimer);const q=input.value.trim();s.searchQuery=q;s.error='';if(q.length<2){s.searchResults=[];out.innerHTML='';status.textContent='';return}searchTimer=setTimeout(async()=>{status.textContent='Zoeken…';try{const items=await search(q);if(q!==s.searchQuery)return;s.searchResults=items;status.textContent=items.length?'':'Geen bestemmingen gevonden.';out.innerHTML=items.map((x,i)=>`<button data-result-index="${i}"><b>${esc(x.name)}</b><small>${esc(x.address)}</small></button>`).join('')}catch(e){if(e?.name!=='AbortError')status.textContent=e?.message||'Zoeken mislukt.'}},350)})}
async function prepare(){try{s.loading=true;s.error='';s.screen='preview';render();const p=await geo();s.pos={latitude:p.coords.latitude,longitude:p.coords.longitude,speed:Number(p.coords.speed||0),accuracy:p.coords.accuracy};s.origin={name:'Huidige locatie',latitude:s.pos.latitude,longitude:s.pos.longitude};await route(true);s.screen='preview';render()}catch(e){s.loading=false;s.error=e?.code===1?'Geef MAIR locatietoegang om een route te starten.':e?.message||'Route voorbereiden mislukt.';s.screen='search';render();queueMicrotask(bindSearch)}}
function render(){ensure();if(!open)return;if(s.screen==='home')overlay.innerHTML=startMarkup();else if(s.screen==='search'){overlay.innerHTML=searchMarkup();queueMicrotask(bindSearch)}else if(s.screen==='preview')overlay.innerHTML=s.loading?`<section class="car-loading"><b>${esc(s.destination?.name||'Bestemming geselecteerd')}</b><span>GPS en verkeer ophalen…</span></section>`:previewMarkup();else if(s.screen==='drive')overlay.innerHTML=s.near?focusMarkup():player(true);else overlay.innerHTML=player(false)}
const wakeSupported=()=>!!navigator.wakeLock?.request;function wakeRetryStart(){if(wakeRetry)clearTimeout(wakeRetry);if(open&&document.visibilityState==='visible'&&wakeSupported())wakeRetry=setTimeout(()=>requestWake(),1500)}async function requestWake(){if(!open||document.visibilityState!=='visible'||!wakeSupported())return false;if(wake&&!wake.released)return true;try{const l=await navigator.wakeLock.request('screen');wake=l;l.addEventListener('release',()=>{if(wake===l)wake=null;wakeRetryStart()},{once:true});return true}catch{wake=null;return false}}async function releaseWake(){if(wakeRetry){clearTimeout(wakeRetry);wakeRetry=null}const l=wake;wake=null;if(l&&!l.released)try{await l.release()}catch{}}
function setOpen(v){ensure();open=!!v;overlay.classList.toggle('is-open',open);document.body.classList.toggle('mair-car-mode-open',open);if(open){document.body.dataset.mairCarMode='1';s.screen=s.routeActive?'drive':'home';if(s.routeActive){watch();startRefresh()}config().then(render);requestWake();render()}else{delete document.body.dataset.mairCarMode;unwatch();stopRefresh();closeMenu();releaseWake()}try{window.dispatchEvent(new CustomEvent('mair:car-mode',{detail:{open}}))}catch{}}
document.addEventListener('keydown',e=>{if(open&&e.key==='Escape')setOpen(false)});document.addEventListener('visibilitychange',()=>{if(!open)return;document.visibilityState==='visible'?requestWake():releaseWake()});window.addEventListener('pageshow',()=>{if(open)requestWake()});window.addEventListener('pagehide',()=>releaseWake());['jfm:trackchange','jfm:playback-state','jfm:upcoming-invalidated','mair:director-replanned','mair:channelchange'].forEach(n=>window.addEventListener(n,()=>{if(open)render()}));
window.MAIRCarModePrototype={version:'journey-nav-v3-search-fix-2026-08-30',open:()=>setOpen(true),close:()=>setOpen(false),toggle:()=>setOpen(!open),render,chooseDestination:()=>{s.screen='search';render()},status:()=>({open,screen:s.screen,routeActive:s.routeActive,destination:s.destination,wakeLockSupported:wakeSupported(),wakeLockActive:!!(wake&&!wake.released),journey:window.MAIRJourneyContext||null})};
})();
